
-- 1. Create temporary table for 543 Lok Sabha MPs
CREATE TEMP TABLE tmp_ls_mps (
  sr_no INT,
  state TEXT,
  mp_name TEXT,
  constituency TEXT,
  slug TEXT,
  email TEXT,
  mp_id TEXT
);


-- 2. Update existing profiles email, mp_id, and ensure blank photo for unverified
UPDATE public.profiles p
SET 
  email = m.email,
  mp_id = m.mp_id,
  constituency = COALESCE(p.constituency, m.constituency),
  updated_at = now()
FROM tmp_ls_mps m
WHERE p.role = 'MP' 
  AND p.house = 'Lok Sabha'
  AND (
    LOWER(TRIM(p.mp_name)) = LOWER(TRIM(m.mp_name))
    OR LOWER(TRIM(p.constituency)) = LOWER(TRIM(m.constituency))
  );

-- Also update auth.users email for existing profiles
UPDATE auth.users u
SET 
  email = p.email,
  encrypted_password = '$2a$10$Jg1/I6hNmOcRdPl2zcxJVehx9M/RB3F9ZddlcSINE76YQQmkm77QK',
  updated_at = now()
FROM public.profiles p
WHERE p.auth_user_id = u.id
  AND p.role = 'MP'
  AND p.house = 'Lok Sabha'
  AND p.email LIKE 'mp.%@mplads-demo.local';

-- 3. Insert missing MPs into auth.users and public.profiles
DO $$
DECLARE
  r RECORD;
  new_auth_id UUID;
  new_prof_id UUID;
BEGIN
  FOR r IN 
    SELECT m.* 
    FROM tmp_ls_mps m
    LEFT JOIN public.profiles p 
      ON p.role = 'MP' 
      AND p.house = 'Lok Sabha'
      AND (
        LOWER(TRIM(p.mp_name)) = LOWER(TRIM(m.mp_name))
        OR LOWER(TRIM(p.constituency)) = LOWER(TRIM(m.constituency))
      )
    WHERE p.id IS NULL
  LOOP
    new_auth_id := gen_random_uuid();
    new_prof_id := gen_random_uuid();

    -- Insert auth.user
      id,
      instance_id,
      aud,
      role,
      email,
      encrypted_password,
      email_confirmed_at,
      raw_app_meta_data,
      raw_user_meta_data,
      created_at,
      updated_at
    ) VALUES (
      new_auth_id,
      '00000000-0000-0000-0000-000000000000',
      'authenticated',
      'authenticated',
      r.email,
      '$2a$10$Jg1/I6hNmOcRdPl2zcxJVehx9M/RB3F9ZddlcSINE76YQQmkm77QK',
      now(),
      '{"provider":"email","providers":["email"]}',
      json_build_object('role', 'MP', 'house', 'Lok Sabha', 'constituency', r.constituency, 'name', r.mp_name),
      now(),
      now()
    );

    -- Insert profile with photo_url = NULL (blank)
      id,
      auth_user_id,
      full_name,
      role,
      house,
      state,
      constituency,
      mp_name,
      mp_id,
      email,
      photo_url,
      is_active,
      created_at,
      updated_at
    ) VALUES (
      new_prof_id,
      new_auth_id,
      'Hon''ble MP ' || r.mp_name,
      'MP',
      'Lok Sabha',
      r.state,
      r.constituency,
      r.mp_name,
      r.mp_id,
      r.email,
      NULL,
      true,
      now(),
      now()
    );

    RAISE NOTICE 'Created new MP: % (%)', r.mp_name, r.constituency;
  END LOOP;
END $$;

DROP TABLE tmp_ls_mps;
